'use client';

// Generated by the paper→experiment pipeline from Ramachandran & Hubbard (2001),
// "Synaesthesia — A Window Into Perception, Thought and Language" (Fig. 7, the
// bouba/kiki demonstration). Paradigm: 2-alternative forced choice — a made-up word
// is shown with a rounded and a spiky shape; the participant picks the shape the word
// "belongs to". Expected effect: ~95% map rounded→bouba/maluma and spiky→kiki/takete.
//
// Self-contained: inline SVG stimuli, results kept in local state. DB persistence +
// teacher dashboard are added in later pipeline steps.

import { useState, useEffect, useRef } from 'react';

type WordType = 'rounded' | 'spiky';

interface Word {
  text: string;
  type: WordType;
}

const WORDS: Word[] = [
  { text: 'BOUBA', type: 'rounded' },
  { text: 'MALUMA', type: 'rounded' },
  { text: 'KIKI', type: 'spiky' },
  { text: 'TAKETE', type: 'spiky' },
];

interface Trial {
  word: Word;
  roundedOnLeft: boolean;
}

interface Result {
  word: string;
  wordType: WordType;
  chose: WordType;
  conventional: boolean; // rounded word → rounded shape (or spiky → spiky)
  rtMs: number;
}

const N_TRIALS = 12;

function makeTrials(): Trial[] {
  const trials: Trial[] = [];
  for (let i = 0; i < N_TRIALS; i++) {
    trials.push({ word: WORDS[i % WORDS.length], roundedOnLeft: Math.random() < 0.5 });
  }
  for (let i = trials.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [trials[i], trials[j]] = [trials[j], trials[i]];
  }
  return trials;
}

// ── Inline SVG stimuli (no external assets) ──────────────────────────────────
function starPoints(spikes = 8, outer = 46, inner = 18): string {
  const pts: string[] = [];
  for (let i = 0; i < spikes * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (Math.PI * i) / spikes - Math.PI / 2;
    pts.push(`${(50 + r * Math.cos(a)).toFixed(1)},${(50 + r * Math.sin(a)).toFixed(1)}`);
  }
  return pts.join(' ');
}
const STAR = starPoints();

function Shape({ type, size = 130 }: { type: WordType; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden>
      {type === 'rounded' ? (
        <path
          d="M50 8 C 78 8, 93 28, 89 52 C 85 80, 60 95, 40 90 C 14 84, 6 58, 12 36 C 18 15, 33 8, 50 8 Z"
          fill="#a78bfa"
        />
      ) : (
        <polygon points={STAR} fill="#a78bfa" />
      )}
    </svg>
  );
}

// ── Copy (Hebrew default, English toggle) ────────────────────────────────────
const T = {
  he: {
    title: 'איזו צורה מתאימה למילה?',
    intro: 'בכל שלב תופיע מילה מומצאת ושתי צורות. לחצו על הצורה שנשמעת לכם מתאימה למילה. אין תשובה נכונה או שגויה — פשוט בחרו לפי התחושה.',
    begin: 'התחל',
    prompt: 'לאיזו צורה מתאימה המילה',
    doneTitle: 'סיימת!',
    conventional: 'התאמת את המיפוי המקובל',
    ofTrials: 'מתוך',
    again: 'שוב',
    lang: 'English',
  },
  en: {
    title: 'Which shape fits the word?',
    intro: 'On each screen you see a made-up word and two shapes. Click the shape that feels like it matches the word. There is no right or wrong answer — just go with your gut.',
    begin: 'Begin',
    prompt: 'Which shape is a',
    doneTitle: 'Done!',
    conventional: 'You chose the conventional mapping on',
    ofTrials: 'of',
    again: 'Again',
    lang: 'עברית',
  },
};

export default function BoubaKikiPaperExperiment() {
  const [lang, setLang] = useState<'he' | 'en'>('he');
  const [phase, setPhase] = useState<'intro' | 'task' | 'done'>('intro');
  const [trials, setTrials] = useState<Trial[]>([]);
  const [idx, setIdx] = useState(0);
  const [results, setResults] = useState<Result[]>([]);
  const startRef = useRef<number>(0);

  const t = T[lang];

  useEffect(() => {
    const stored = sessionStorage.getItem('bkp_language') as 'he' | 'en' | null;
    if (stored) setLang(stored);
  }, []);

  useEffect(() => {
    if (phase === 'task') startRef.current = performance.now();
  }, [phase, idx]);

  const start = () => {
    setTrials(makeTrials());
    setResults([]);
    setIdx(0);
    setPhase('task');
  };

  const choose = (chose: WordType) => {
    const trial = trials[idx];
    const result: Result = {
      word: trial.word.text,
      wordType: trial.word.type,
      chose,
      conventional: chose === trial.word.type,
      rtMs: Math.round(performance.now() - startRef.current),
    };
    const next = [...results, result];
    setResults(next);
    if (idx + 1 >= trials.length) setPhase('done');
    else setIdx(idx + 1);
  };

  const toggleLang = () => {
    const nl = lang === 'he' ? 'en' : 'he';
    setLang(nl);
    sessionStorage.setItem('bkp_language', nl);
  };

  return (
    <div
      dir={lang === 'he' ? 'rtl' : 'ltr'}
      style={{ height: '100dvh' }}
      className="bg-[#0f172a] text-white flex flex-col"
    >
      {/* Top bar: language toggle + progress */}
      <div className="flex-shrink-0">
        <div className="flex justify-end p-3">
          <button
            onClick={toggleLang}
            className="px-3 py-1.5 text-sm text-purple-400 hover:text-purple-300 hover:bg-gray-800 rounded-lg transition-colors touch-manipulation"
          >
            {t.lang}
          </button>
        </div>
        {phase === 'task' && (
          <div className="h-1.5 bg-gray-800">
            <div
              className="h-full bg-purple-500 transition-all duration-300"
              style={{ width: `${(idx / trials.length) * 100}%` }}
            />
          </div>
        )}
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 text-center gap-8">
        {phase === 'intro' && (
          <>
            <h1 className="text-2xl font-bold text-purple-400">{t.title}</h1>
            <p className="max-w-md text-gray-300 leading-relaxed">{t.intro}</p>
            <button
              onClick={start}
              className="px-8 py-3 bg-purple-500 hover:bg-purple-400 text-white font-bold rounded-xl transition-colors touch-manipulation"
            >
              {t.begin}
            </button>
          </>
        )}

        {phase === 'task' && trials[idx] && (
          <>
            <p className="text-gray-400">{t.prompt}</p>
            <div
              className="text-5xl font-bold tracking-widest text-white"
              style={{ fontFamily: 'monospace' }}
            >
              {trials[idx].word.text}
            </div>
            <div className="flex gap-10 items-center" style={{ direction: 'ltr' }}>
              {(trials[idx].roundedOnLeft
                ? (['rounded', 'spiky'] as WordType[])
                : (['spiky', 'rounded'] as WordType[])
              ).map((shapeType, i) => (
                <button
                  key={i}
                  onClick={() => choose(shapeType)}
                  className="p-4 rounded-2xl border border-gray-700 hover:border-purple-400 hover:bg-gray-800 transition-colors touch-manipulation"
                  aria-label={shapeType}
                >
                  <Shape type={shapeType} />
                </button>
              ))}
            </div>
          </>
        )}

        {phase === 'done' && (
          <>
            <h1 className="text-2xl font-bold text-purple-400">{t.doneTitle}</h1>
            <p className="text-lg text-gray-200">
              {t.conventional}{' '}
              <span className="font-bold text-emerald-400">
                {results.filter((r) => r.conventional).length}
              </span>{' '}
              {t.ofTrials} {results.length}
            </p>
            <button
              onClick={start}
              className="px-8 py-3 bg-gray-800 hover:bg-gray-700 text-gray-300 rounded-xl border border-gray-600 transition-colors touch-manipulation"
            >
              {t.again}
            </button>
          </>
        )}
      </div>
    </div>
  );
}
